/* @lc app=leetcode id=3548 lang=kotlin */ class Solution { fun can(rows: Int, n: Int, c: Map<Int, Int>, v: Long, a: Int, b: Int): Boolean = if (v > 100000L) false else v.toInt().let { vi -> if (rows >= 2 && n >= 2) (c[vi] ?: 0) > 0 else a == vi || b == vi } fun h(g: Array<IntArray>): Boolean = g.size.let { m -> g[0].size.let { n -> g.sumOf { r -> r.sumOf { it.toLong() } }.let { tot -> HashMap<Int, Int>().let { top -> HashMap<Int, Int>().also { bot -> g.forEach { r -> r.forEach { bot.merge(it, 1) { a, b -> a + b } } } }.let { bot -> LongArray(1).let { s1 -> (0 until m - 1).any { i -> g[i].forEach { v -> top.merge(v, 1) { a, b -> a + b }.also { bot.merge(v, -1) { a, b -> a + b } } }.let { s1[0] += g[i].sumOf { it.toLong() } }.let { (s1[0] * 2 - tot).let { df -> if (df == 0L) true else if (df > 0) can(i + 1, n, top, df, g[0][0], g[i][n - 1]) else can(m - 1 - i, n, bot, -df, g[i + 1][0], g[m - 1][n - 1]) } } } } } } } } } fun canPartitionGrid(grid: Array<IntArray>): Boolean = h(grid) || h(Array(grid[0].size) { j -> IntArray(grid.size) { i -> grid[i][j] } }) }